   180  light_pcapng_t *light_pcapng_open_read(const char* file_path, light_boolean read_all_interfaces)
   181  {
   182          DCHECK_NULLP(file_path, return NULL);
   183
   184          light_pcapng_t *pcapng = calloc(1, sizeof(struct _light_pcapng_t));
   185          pcapng->file = light_open(file_path, LIGHT_OREAD);
   186          DCHECK_ASSERT_EXP(pcapng->file != NULL, "could not open file", return NULL);
   187
   188          //The first thing inside an NG capture is the section header block
   189          //When the file is opened we need to go ahead and read that out
   190          light_read_record(pcapng->file,&pcapng->pcapng);
   191          //Prase stuff out of the section header
   192          pcapng->file_info = __create_file_info(pcapng->pcapng);
   193
   194          //If they requested to read all interfaces we must fast forward through file and find them all up front
   195          if (read_all_interfaces)
   196          {
   197                  //Bookmark our current location
   198                  light_file_pos_t currentPos = light_get_pos(pcapng->file);
   199                  while (pcapng->pcapng != NULL)
   200                  {
   201                          light_read_record(pcapng->file, &pcapng->pcapng);
   202                          uint32_t type = LIGHT_UNKNOWN_DATA_BLOCK;
   203                          light_get_block_info(pcapng->pcapng, LIGHT_INFO_TYPE, &type, NULL);
   204                          if (type == LIGHT_INTERFACE_BLOCK)
   205                                  __append_interface_block_to_file_info(pcapng->pcapng, pcapng->file_info);
   206                  }
   207                  //Should be at and of file now, if not something broke!!!
   208                  if (!light_eof(pcapng->file))
   209                  {
   210                          light_pcapng_release(pcapng->pcapng);
   211                          return NULL;
   212                  }
   213                  //Ok got to end of file so reset back to bookmark
   214                  light_set_pos(pcapng->file, currentPos);
   215          }
   216
   217          light_pcapng_release(pcapng->pcapng);
   218          pcapng->pcapng = NULL;
   219
   220          return pcapng;
   221  }
